function uniqueImportedEntityId(rawId, usedIds, validateId, fallbackPrefix) {
  const fallback = `${fallbackPrefix}_${randomUUID().replace(/-/g, '').slice(0, 12)}`;
  const base = validateId(rawId || fallback);
  if (!usedIds.has(base)) {
    usedIds.add(base);
