  }
  for (let attempt = 0; attempt < 1000; attempt++) {
    const candidate = validateId(`${base}_imported_${randomUUID().replace(/-/g, '').slice(0, 12)}`);
    if (!usedIds.has(candidate)) {
      usedIds.add(candidate);
      return candidate;
