async function exportBackup(options = {}) {
  const cfg = await loadConfig();
  const selected = options?.vaultId
    ? cfg.vaults.filter(v => v.id === validateEntityId(options.vaultId, 'vault'))
    : cfg.vaults;
  const vaults = [];
  const warnings = [];
  for (const v of selected) {
